// TestDareWeakLargeModeHonest holds Dare and Dlqr to their error contract
// on weakly controllable large modes: a nil error only with X and K
// honest (within max(1e-7, 100·spread) of the 320-bit Hewer solution from
// the returned K), ErrAccuracyUnverified with the result in full.
func TestDareWeakLargeModeHonest(t *testing.T) {
	for _, c := range weakLargeModeRows {
		for _, api := range []string{"Dare", "Dlqr"} {
			for _, ns := range []bool{false, true} {
				opts := &RiccatiOpts{E: c.E, NoScaling: ns}
				solve := Dare
				if api == "Dlqr" {
					solve = Dlqr
				}
				res, err := solve(c.A, c.B, c.Q, c.R, opts)
				switch {
				case errors.Is(err, ErrAccuracyUnverified):
					if res == nil || res.X == nil || res.K == nil {
						t.Errorf("%s %s ns=%v: unverified without result", c.name, api, ns)
					}
					continue
				case err != nil:
					continue
				}
				pr := nearSingularRiccati{A: c.A, B: c.B, Q: c.Q, R: c.R, E: c.E, generalized: api == "Dare"}
				if ex, ek, ok := pr.honest(t, res.X, res.K); !ok {
					t.Errorf("%s %s ns=%v: certified with K %.3g, X %.3g off the 320-bit solution", c.name, api, ns, ek, ex)
				}
			}
		}
	}
}

// TestReducedGainNewtonUnproven feeds the reduced-input gate the X and K
// that Dare certified for arm64 zrw big 10446 on gonum v0.20.10: within
// 1e-9 of their own Hewer iterate in exact arithmetic, 0.17 and 0.2 off
// the 320-bit solution, with the Newton–Kantorovich h near 1e20. The gate
// must not accept them.
func TestReducedGainNewtonUnproven(t *testing.T) {
	c := weakLargeModeRows[0]
	for _, r := range weakLargeModeRows {
		if r.name == "arm64 10446" {
			c = r
		}
	}
	opts := &RiccatiOpts{E: c.E}
	X := mat.NewDense(2, 2, []float64{1.7724375917753828e+25, -1.488162703102e+25, -1.488162703102e+25, 1.2494816410915453e+25})
	K := mat.NewDense(3, 2, []float64{4.124994857997649e+12, -2.621497149063337e+12, -3.371253942919774e+11, 2.1424833010385208e+11, -2.205907959707569e+10, 1.4018881541143198e+10})
	const step = 3.5966770340945995e-12
	red, _ := reduceInputs(c.A, c.B, c.Q, c.R, opts)
	if red == nil || red.rotated {
		t.Fatalf("want reduced inputs, got %+v", red)
	}
	if h, ok := newtonKantorovich(c.A, c.B, opts, red, X, K, step); !ok || h <= 0.5 {
		t.Fatalf("h %.3g ok %v, want > 0.5", h, ok)
	}
	res := &RiccatiResult{X: X, K: K, Eig: []complex128{0.3065736473417928, -2.32782766293698e-05}, step: step}
	if r, _, ok := unprovenReduced(c.A, c.B, c.Q, c.R, opts, red, res, gainDist{}); ok {
		t.Fatalf("gate accepted K %v", mat.Formatted(r.K))
	}
}

// TestReducedGainNewtonProven is the gate's control: a well-conditioned
// Dare with duplicated inputs keeps its certified K.
func TestReducedGainNewtonProven(t *testing.T) {
	A := mat.NewDense(3, 3, []float64{0.9, 0.3, -0.2, 0.1, 1.1, 0.4, -0.3, 0.2, 0.7})
	B := mat.NewDense(3, 2, []float64{1, 1, 0.5, 0.5, -0.2, -0.2})
	Q, R := eyeDense(3), eyeDense(2)
	E := mat.NewDense(3, 3, []float64{1.2, 0.3, -0.1, 0, 0.9, 0.2, 0, 0, 1.1})
	opts := &RiccatiOpts{E: E}
	res, err := Dare(A, B, Q, R, opts)
	if err != nil {
		t.Fatal(err)
	}
	red, _ := reduceInputs(A, B, Q, R, opts)
	if red == nil {
		t.Fatal("want reduced inputs")
	}
	if newtonUnproven(A, B, opts, red, res.X, res.K, res.step) {
		h, _ := newtonKantorovich(A, B, opts, red, res.X, res.K, res.step)
		t.Fatalf("h %.3g on a well-conditioned Dare", h)
	}
	if _, _, ok := unprovenReduced(A, B, Q, R, opts, red, res, gainDist{}); !ok {
		t.Fatal("gate rejected a proven K")
	}
}

// TestDareUnprovenReducedTakesHewerSolution: zrw "reg" rows with
// duplicated inputs, n 2, m 3, whose Newton certificate newtonUnproven
// voids. On base 2d35ddd Dare and Dlqr returned them at Accuracy 0 with X
// 2.3e-7 and 5.5e-8 off the 320-bit X, within their eps-sensitivity; held
// to newtonTol of the Hewer X (hewerGainConverged) they lost it. They
// take the converged Hewer solution (hewerSolution) and stay honest.
func TestDareUnprovenReducedTakesHewerSolution(t *testing.T) {
	rows := []struct {
		name          string
		A, B, Q, R, E *mat.Dense
	}{
		{"arm64 10723", mat.NewDense(2, 2, []float64{-1.2197256322088657, 1.4312058528359228, -0.018423537693470795, 0.511295171556246}), mat.NewDense(2, 3, []float64{0.2407315545338694, -2.1065916246064065, -0.27338813251327604, 0.21990214533677035, -1.924317809091415, -0.2497330977891719}), mat.NewDense(2, 2, []float64{1.0000000000000004, 1.734496616373932e-16, 1.734496616373932e-16, 1.0000000000000002}), mat.NewDense(3, 3, []float64{1, 0, 0, 0, 1, 0, 0, 0, 1}), mat.NewDense(2, 2, []float64{0.9796081266568227, 0.20091769008205976, -0.20091769008205973, 0.9796081266568226})},
		{"arm64 11090", mat.NewDense(2, 2, []float64{-1.8163446828033731, 0.2813312516770279, -0.5880739848334703, 1.302135624434151}), mat.NewDense(2, 3, []float64{0.43222861102209503, 0.2819091481900545, 0.4117885563717604, 0.6064655250411508, 0.39555035216113266, 0.5777858205714079}), mat.NewDense(2, 2, []float64{0.9999999999999998, 1.4977138920573913e-16, 1.4977138920573913e-16, 1}), mat.NewDense(3, 3, []float64{1, 0, 0, 0, 1, 0, 0, 0, 1}), mat.NewDense(2, 2, []float64{-0.5310387325938336, -1.0222298998161288, 1.2153553285919614, -0.5269077967544865})},
	}
	for _, c := range rows {
		for _, api := range []string{"Dare", "Dlqr"} {
			solve := Dare
			if api == "Dlqr" {
				solve = Dlqr
			}
			res, err := solve(c.A, c.B, c.Q, c.R, &RiccatiOpts{E: c.E})
			if err != nil {
				t.Errorf("%s %s: %v", c.name, api, err)
				continue
			}
			pr := nearSingularRiccati{A: c.A, B: c.B, Q: c.Q, R: c.R, E: c.E, generalized: api == "Dare"}
			if ex, ek, ok := pr.honest(t, res.X, res.K); !ok {
				t.Errorf("%s %s: K %.3g, X %.3g off the 320-bit solution", c.name, api, ek, ex)
			}
		}
	}
}
